INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('true-megahorse', 'True Megahorse', 'beast', 'rifts', 0, 'Any; most are Principled (20%), Scrupulous (25%), Unprincipled (20%) or Aberrant (15%)', '{"IQ":"1D4+6","ME":"2D6+8","MA":"2D4+6","PS":"3D6+20","PP":"2D6+12","PE":"2D6+12","PB":"2D6+14","Spd":"4D6+58"}', NULL, NULL, 'PEx10', '6D6+6', 'MEx2', 'M.D.C. is P.E. x10 plus 3D6 per level of experience, on the Explorer O.C.C. experience table. I.S.P. is M.E. x2 plus 1D6 per level. P.S. is Supernatural. Spd works out to 42-58 mph (67 to 93 km) at the least.', NULL, 12, '{"attacks":3,"initiative":3,"strike":3,"dodge":5,"roll":3}', 'Awe/Horror Factor 12, +3 only while charging. +1 attack at levels 2, 4, 6, 9, 12 and 15. +1 to save vs magic, +2 vs poison and disease, +3 vs possession, +4 vs Horror Factor. All in addition to attribute bonuses. A front-leg kick does Supernatural P.S. damage, a rear-leg kick that +10, and a rear-leg power kick double for two attacks. Riding bonus: a rider the Megahorse likes and works with gets +10% to horsemanship, and someone with no riding skill rides it as if at 55%.', 'Wilderness Survival (+30%), Land Navigation (+20%), Track Animals, Tracking people (+5%), Dowsing (+5%), Swim, Prowl, understands one language of choice (+5%). Four Technical skills that need no hands at level one, and one more at levels 2, 5, 7, 10 and 13 (read off a render; the text layer prints the 7 as 1). Skills improve with experience.', 'Runs three hours without tiring. Leaps 12 feet (3.6 m) up and 20 feet (6 m) across, plus a yard per 5 points of P.S. from a short gallop and half again at a full one. Day vision is excellent, night sight barely better than human, hearing keen, smell fair. Pulls 15 tons and carries 4. Senses supernatural evil the way an Earth horse does.', 'None', 'Sense Evil, Sense Magic, Sense Time, Empathy, Telepathy, Mask I.S.P. & Psionics, Mind Block, Telekinetic Push, Psionic Invisibility', '10-12 feet (3 to 3.6 m) long; about 7-8 feet (2.1 to 2.4 m) at the shoulders', '1 to 1.4 tons', '150-220 years', 'From an alien world; comfortable in most climates, preferring forests, jungles and open grassland such as the steppe. About 76,000 in Russia, some 10,000 more suspected in China, a few hundred elsewhere', 'Heroes, knights and those who fight supernatural evil; fond of War-Knights, Bogatyr, Cossacks, Huntsmen and Mystic Kuznya; favors children and the gentle', 'Demons and all supernatural evil, Necromancers, Witches, large predators, would-be enslavers', 'No O.C.C.; something like an animal knight or Bogatyr. Meant mainly as an NPC, but bright enough that the book allows one as a player character in theory. It chooses its own rider and cannot be broken like a riding animal. Only 14% of War-Knights have one. Value 15-20 million credits or more, though it will not submit to being bought and sold.', 'A marble-white alien horse half again the size of a war horse, as smart as a person, with empathic and telepathic gifts and a standing hatred of supernatural evil. It partners with riders it judges worthy and carries nobody else.', 'Rifts World Book 17: Warlords of Russia p.164-165'),
('horned-steed', 'Horned Steed (Devil Horse)', 'animal', 'rifts', 0, 'Animal; generally considered good or anarchist', '{"IQ":"1D4+4","ME":"2D6+6","MA":"2D6+10","PS":"3D6+12","PP":"2D6+8","PE":"2D6+8","PB":"2D6+4","Spd":"48+3D6"}', NULL, NULL, '3D6x6+PE', '4D6', NULL, 'M.D.C. is 3D6x6 plus the P.E. attribute number. P.S. is Supernatural. Spd is 35 to 45 mph (56 to 72 km). High animal intelligence.', NULL, 9, '{"attacks":3,"initiative":2,"strike":3,"parry":1,"dodge":4}', 'Awe/Horror Factor 9. All bonuses are in addition to attribute bonuses. The charging ram counts as two attacks and has a 01-50% chance to knock a human-sized opponent down, costing initiative and two melee actions.', 'Land navigation 80%, prowl 40%, swim 65%.', 'Runs flat out for an hour, or trots at 20 mph (32 km) for four hours, before it tires. Carries 1,000 pounds (450 kg) and pulls ten tons. Sight, hearing and smell are all good, and it sees in the dark out to 600 feet (183 m). Leaps six feet (1.8 m) up and 12 feet (3.6 m) across, a third farther at a gallop. Leathery plates armor the head, neck and spine.', 'None', 'None', '6-8 feet (1.8 to 2.4 m) long; 5 to 5.4 feet (1.5 to 1.6 m) at the shoulders, about 7 feet (2.1 m) overall', '1200-1800 pounds (544 to 816 kg)', '24-30 years', 'Western Russia, the Steppe, southern Siberia in summer, Mongolia and China. Loves grassland and moderate climates but survives Siberian winters. Millions run wild and at least a million are domesticated', 'Not applicable; as easy to domesticate as an Earth horse', 'Large predators, pack hunters such as wolves, humanoids', 'No O.C.C.; an animal. Worth 2,000-4,000 credits as a riding animal or beast of burden. The hide makes light M.D. leather armor of 25 M.D.C., or 35-55 in a composite suit. A favorite of Cossacks, War-Knights and messengers.', 'A horse from another dimension with a pair of devil-like horns and armored plating down its head, neck and back. It grazes, herds and behaves much as an Earth horse does, and it butts and rams like a bull.', 'Rifts World Book 17: Warlords of Russia p.165-166'),
('burkov-mastodon', 'Burkov Mastodon', 'animal', 'rifts', 0, 'Animal; generally considered selfish', '{"IQ":"1D4+2","ME":"1D6+6","MA":"1D6+6","PS":"2D6+40","PP":"10+1D6","PE":"20+1D6","PB":"2D6+2","Spd":"33+2D4"}', NULL, NULL, '2D6x10+110', '3D6', NULL, 'Spd has a minimum of 22 mph (36 km). Medium animal intelligence.', NULL, 9, '{"attacks":3,"initiative":1,"strike":3,"parry":2,"dodge":1}', 'Horror Factor 9, +3 only while charging. +6 to save vs Horror Factor. Females, slightly the larger, have three attacks per round and do an extra 1D6 M.D. except on restrained attacks; males have four attacks. The tusks club rather than impale, and can pin an attacker or toss it up to 20 feet (6 m).', 'Finds edible plants and roots under as much as eight feet (2.4 m) of snow at 75%; swim 60%; land navigation 45%.', 'Runs at top speed for an hour, or walks and trots at 6-10 mph (9.6 to 16 km) for six. Carries ten tons and pulls 60; the tusks and neck lift or roll aside four tons. Fair vision and a keen nose. The neck is 7-9 feet long and turns the head 180 degrees to either side. A gentle plant-eater that is easy to train, until something threatens it.', 'None', 'None', 'Body 14-16 feet (4.2 to 4.8 m); 24-30 feet (7.3 to 9 m) from tusk tip to hindquarters, plus a 3-4 foot tail. 10-12 feet (3 to 3.6 m) at the shoulders, 15-18 feet (4.6 to 5.5 m) overall', '7-9 tons', '25-30 years', 'The steppe and tundra of Russia, and forests in cold to moderate climates. An estimated half million in the Russian wilderness, likely three to five times that; at least 35,000 domesticated. A wild herd is 4D4x100', 'Not applicable; domesticated by Cossacks and others', 'Large predators, pack hunters, humanoids', 'No O.C.C.; an animal. Worth 5,000-10,000 credits as a beast of burden or mount. The hide makes light M.D. leather armor of 20 M.D.C., or 40-50 in a composite suit. One yields the meat of 10-16 cows but eats too much to raise as cattle.', 'A woolly, tusked alien beast the size of an elephant and built more like a huge rhinoceros, with its head slung low for grazing. It is the heavy hauler of the Russian north and of the long winters.', 'Rifts World Book 17: Warlords of Russia p.167-168'),
('steppe-ostrich', 'Steppe Ostrich', 'animal', 'rifts', 0, 'Animal; generally considered evil or anarchist', '{"IQ":"1D4","ME":"1D6+6","MA":"1D6","PS":"2D6+12","PP":"16+1D6","PE":"16+1D6","PB":"2D6","Spd":"45+2D6"}', NULL, NULL, '4D6+PE', '2D6', NULL, 'M.D.C. is 4D6 plus the P.E. attribute number. Spd is 30-38 mph (48 to 60.8 km). Low animal intelligence.', NULL, 9, '{"attacks":4,"initiative":4,"strike":4,"parry":1,"dodge":3}', 'Horror Factor 9 alone; an attacking flock has 14. +3 to save vs poison and disease. All bonuses are in addition to attribute bonuses.', 'Tracks by sight at 50%; land navigation 85%; prowl 50%. Cannot swim.', 'Runs at top speed for an hour or trots at 18 mph (29 km) for five. Three times an hour, at the start of a melee round, it can sprint half again as fast (about 48 mph/77 km) for 1D4 minutes. Leaps 12 feet (3.6 m) up or across from a short run and 20 feet (6 m) at full speed. Carries 500 pounds (225 kg) and pulls a ton. Keen-eyed, with good hearing and a good nose; sees in the dark out to 200 feet (61 m) and into the ultraviolet. Hates water.', 'None', 'None', '8-10 feet (2.4 to 3 m) tall to the top of the head; 4.6 to 5 feet (1.4-1.5 m) at the shoulders; about 4-5 feet (1.2 to 1.5 m) long', '250 to 400 pounds (112.5 to 180 kg)', '15-20 years', 'The steppe and light forests of southern Russia, Mongolia and China, in the millions. Flocks of 5D6, sometimes 2D4x10', 'Not applicable; can be domesticated', 'Other large predators, pack hunters such as wolves, humanoids', 'No O.C.C.; an animal. Worth 300-500 credits, raised mainly for meat (one equals 12-18 chickens) and ridden by Mongols and Chinese; Cossacks refuse to ride them. Alone or in fours they are skittish; a flock tests prey with runs of 8-16 birds and will go for groups of up to a dozen people, but breaks off from anything that fights hard and never attacks a healthy animal the size of a horse.', 'A giant flightless bird that peasants swear is a mutant chicken, more likely another arrival through the Rifts. It eats grain, scraps, carrion and, in a flock, livestock and people, pouncing from a leap to peck and claw.', 'Rifts World Book 17: Warlords of Russia p.168-169'),
('ursan-forest-steed', 'Ursan Forest Steed', 'animal', 'rifts', 0, 'Animal; generally considered good or anarchist', '{"IQ":"1D4+2","ME":"1D6+10","MA":"2D6+10","PS":"3D6+20","PP":"16+1D6","PE":"10+1D6","PB":"2D6+2","Spd":"38+2D6"}', NULL, NULL, '3D4x10+PE', '4D6', NULL, 'M.D.C. is 3D4x10 plus the P.E. attribute number. P.S. is Supernatural. Spd is 28-35 mph (the book prints 44 to 48 km). Medium animal intelligence.', NULL, 10, '{"attacks":5,"initiative":4,"strike":4,"parry":1,"dodge":3}', 'Horror Factor 10, +3 when attacking. +3 to save vs poison and disease, +3 to save vs Horror Factor. All bonuses are in addition to attribute bonuses. A pounce knocks down anything its size or smaller (two melee actions lost) and has a 01-65% chance to pin the prey, -15% if it is over 12 feet and heavier than a ton; a pinned victim cannot fight back while it bites, and gets one arm free if it claws.', 'Tracks by smell at 50%, +15% on blood or another strong scent; land navigation 85%; prowl 50%; swim 75%.', 'Runs at top speed for an hour or trots at 20 mph (32 km) for four. Leaps six feet (1.8 m) up and eight feet (2.4 m) across from a short run, a third more at full speed. Carries 1,200 pounds (544 kg) and pulls five tons. Sees well, and in the dark out to 600 feet (183 m); its hearing is keen and its nose excellent. Cannot climb trees but keeps its footing on rocky slopes.', 'None', 'None', '8-10 feet (2.4 to 3 m) long; 4-4.6 feet (1.2 to 1.4 m) at the shoulders, 5-6 feet (1.5 to 1.8 m) overall, the head carried about 3-3.6 feet off the ground', '1000-1500 pounds (450 to 675 kg)', '18-24 years', 'Cold and cool forests and mountain forests: western Russia, the Ukraine, Poland, Romania, the Urals, Norway, Sweden, Finland and the northern Russian forests. At least 200,000 domesticated and perhaps ten times that wild', 'Not applicable; can be domesticated', 'Other large predators, pack hunters such as wolves, humanoids', 'No O.C.C.; an animal. Worth 3,000-6,000 credits as a mount, guard animal or beast of burden. The hide makes light M.D. leather armor of 12 M.D.C., or 30-40 in a composite suit. A favorite companion and mount of the Huntsman-Trapper. It has no fear of people but attacks them only if attacked, hurt, old or threatened.', 'A shaggy red-brown alien animal built like a bear in front and a big dog behind, with four small ears lost in its mane. It scavenges and hunts, tames easily, and is as loyal and patient as a dog with those who treat it well.', 'Rifts World Book 17: Warlords of Russia p.169-170');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('warlord-yuri-alekseyevna', 'Yuri Garald Alekseyevna', NULL, 'Warlord', 'rifts', 'Human, full conversion heavy cyborg', '12th level Dimiye Soldati with assassin skills', 12, 'Miscreant', '101', '9 feet (2.7 m)', '900 lbs (405 kg)', '{"IQ":17,"ME":15,"MA":13,"PS":28,"PP":24,"PB":12}', NULL, NULL, 270, 4, NULL, NULL, NULL, '{"attacks":7,"initiative":4,"strike":10,"parry":7,"dodge":7,"pull":6,"roll":3}', 'Death Blow on a natural 20. P.S. 28 is robotic (does M.D.); P.P. 24 and P.B. 12 are bionic; P.E. n/a. Spd 90 mph (144 km), bionic. Hit Points and S.D.C. not applicable: Standard Heavy Machine, 270 M.D.C. main body, plus 280 M.D.C. from heavy body armor (wears either his heavy armor or none).', '[{"name":"Radio: Basic","pct":98},{"name":"Intelligence","pct":95},{"name":"Interrogation","pct":95},{"name":"Literacy: Russian and Euro","pct":90},{"name":"Botany","pct":80},{"name":"Computer Operation","pct":98},{"name":"Pilot: Boat: Motor and Hydrofoils","pct":98},{"name":"Pilot: Hovercycle","pct":98},{"name":"Pilot: Jet Pack","pct":80}]', 'Sniper (+1 on aimed shot). Hand to Hand: Assassin, W.P. Energy Pistols and W.P. Energy Rifles, all at 12th level; W.P. Knife at 8th level.', NULL, 'None', 'None', NULL, 'Full conversion Heavy Machine with a realistic human-looking face; all basic features and weapons of the typical Heavy Machine cyborg', 'Heavy body armor (280 M.D.C.)', 'Roughly 50 million universal credits; 10 billion credits in diamonds, gold and jewelry; 500 million in other personal wealth; plus his city, manufacturing, bionics, land holdings, War Camp and mineral rights', 'Reserved and grandfatherly on the surface, but petty and evil underneath, and willing to approve a massacre whenever he judges it warranted. He rates himself a great strategist while being behind the times, and he habitually underrates his rivals.', 'Trades regularly with the Sovietski and Warlord Burgasov, and secretly with the NGR through criminal contacts', 'Hates Warlord Burgasov; despises Warlord Orloff; dismisses Warlord Romanov', 'The oldest of the seven Warlords and the last of the first generation, kept alive by a Heavy Machine body; he took his huge northern Ural domain 69 years ago by setting two rival Warlords on each other and finishing off the survivor. Rules from the smog-covered mining city named after himself, leaves his War Camp (54,000 troops, green and white, flying dragon symbol) to his commanders, and spends his days breeding flowers in his greenhouses.', 'Rifts World Book 17: Warlords of Russia p.37'),
('warlord-pyotr-burgasov', 'Pyotr Karol Burgasov', 'Pyotr Karol Ivonavich', 'Warlord', 'rifts', 'Human, partial conversion cyborg', '10th level War-Knight', 10, 'Aberrant', '54', '7 feet (2.1 m)', '350 lbs (159 kg)', '{"IQ":14,"ME":17,"MA":22,"PS":22,"PP":18,"PE":21,"PB":9,"Spd":65}', 73, 42, 27, 2, 59, NULL, NULL, '{"attacks":7,"initiative":6,"strike":4,"parry":5,"dodge":5,"roll":4,"disarm":4,"pull":8}', '+2 to save vs possession, +6 to save vs Horror Factor. Critical strike on an unmodified 18, 19 or 20; death blow on a natural 20; jump kick (critical). Attacks per melee include all bonuses. P.S. 22 is the real right arm; the bionic left arm is P.S. 24. Spd 65 is bionic (44 mph, 70 km). M.D.C.: bionic legs 80 each, bionic arm 40, main body (reinforced skeleton) 27. In battle wears heavy environmental armor (100 M.D.C.) or Light Cyborg Armor (140 M.D.C.).', '[{"name":"Basic Math","pct":98},{"name":"Literacy: Russian","pct":80},{"name":"Radio: Basic","pct":98},{"name":"Radio: Scramblers","pct":98},{"name":"Military Etiquette","pct":98},{"name":"Detect Ambush","pct":98},{"name":"Intelligence","pct":98},{"name":"Find Contraband, Weapons and Cybernetics","pct":90},{"name":"Climbing","pct":98},{"name":"Cardsharp","pct":55},{"name":"Computer Operation","pct":60},{"name":"Horsemanship: Knight","pct":98},{"name":"Pilot: Motorcycle","pct":80},{"name":"Pilot: Jet Pack","pct":98}]', 'Boxing. Hand to Hand: Martial Arts; W.P. Axe, W.P. Energy Rifles, W.P. Energy Pistols, W.P. Heavy Energy Weapons, W.P. Knife, W.P. Spear/Polearm; paired weapons.', NULL, 'Lore only', 'Major psychic, 59 I.S.P.: Total Recall, See the Invisible, Sixth Sense, Summon Inner Strength, Impervious to Poison, Mind Block', NULL, 'Partial conversion Light Machine (70%) with his real, unmodified face, real right arm, upper torso and lower abdomen; all basic features and weapons of the typical Light Machine cyborg; cyberlink; fingerjack; headjack; type AA cyber-disguise; wire garrote; palm laser torch; interchangeable parts (legs and left arm); reinforced spine, skull and hip; bionic heart and lungs', 'Heavy environmental armor (100 M.D.C.) or Light Cyborg Armor (140 M.D.C.); escorted by four Cyborg Shocktroopers, four Heavy Machines and six War-Knights of 6th-10th level, plus two hidden 7th level Smoke Soldiers', 'Roughly 100 million universal credits; 2.1 billion credits in personal wealth and liquid assets; plus his Sphere of Influence, cities, manufacturing, bionics, land holdings and War Camp', 'A soldier first and last, content only when fighting or planning the next campaign, with a sharp tactical mind and a commanding presence that his troops revere. He keeps his word to the letter and shows no mercy at all to enemies, monsters or those who serve them.', 'None; trades with the Sovietski, the Poles and Warlords Seriyev, Romanov and Alekseyevna. Likes Seriyev without trusting him', 'Warlord Orloff; survivors of the destroyed Kahzmyr Camp; holds Warlord Alekseyevna in contempt', 'Nicknamed "The Bear of Moskva", or "Peter the Bear". A commoner who rose through the ranks, he was named heir, given the Burgasov name and married to the old Warlord''s daughter on that Warlord''s deathbed, then killed the disinherited sons and spent five years annihilating the rival Kahzmyr Camp. From Novgorod he commands the largest War Camp in Russia (98,000 troops; silver, red and brown; bear claw symbol) and is planning a campaign against the gargoyles of St. Peter''s Spine.', 'Rifts World Book 17: Warlords of Russia p.40'),
('warlord-stephan-kolodenko', 'Stephan Ilyavitch Kolodenko', NULL, 'Warlord', 'rifts', 'Human', 'Effectively a 9th level Operator/Mechanic specializing in cybernetics, and a Warlord', 9, 'Unprincipled', '35', '5 feet, 10 inches (1.78 m)', '180 lbs (81 kg)', '{"IQ":20,"ME":15,"MA":21,"PS":18,"PP":19,"PE":14,"PB":12,"Spd":17}', 73, 42, NULL, 9, NULL, NULL, NULL, '{"attacks":6,"initiative":2,"strike":4,"parry":5,"dodge":5,"roll":3,"pull":3}', '+2 to save vs Horror Factor. Critical strike on an unmodified 18-20; jump kick (critical); entangle. Attacks per melee include all bonuses. NOT included in the listed bonuses: the ear implant with amplified hearing gives +3 on initiative, +1 to parry, +2 to dodge.', '[{"name":"Basic and Advanced Math","pct":98},{"name":"Literacy: Russian and Euro","pct":90},{"name":"Computer Operation","pct":98},{"name":"Computer Programming","pct":90},{"name":"Radio: Basic","pct":98},{"name":"Radio: Scramblers","pct":98},{"name":"Electrical Engineer","pct":98},{"name":"Mechanical Engineer","pct":98},{"name":"Robot Mechanics","pct":85},{"name":"Aircraft Mechanics","pct":65},{"name":"Military Etiquette","pct":98},{"name":"Climbing","pct":98},{"name":"Pilot: Hover Vehicles","pct":98},{"name":"Pilot: Jet Pack","pct":98}]', 'Body Building. Hand to Hand: Martial Arts; W.P. Knife, W.P. Energy Rifles, W.P. Energy Pistols; paired weapons.', NULL, 'None', 'None', NULL, 'Gyro-compass; clock calendar; universal headjack and ear implant with amplified hearing', 'Light M.D.C. Trapper''s armor, often worn in public', 'Roughly 100 million universal credits; 2.1 billion credits in personal wealth and liquid assets; plus his Sphere of Influence, cities, manufacturing, bionics, land holdings and War Camp', 'Quick-witted, observant and personable, a cultured man who wears his learning lightly and truly looks after his subjects. He prefers negotiation to bloodshed but does not flinch from a hard call, and he is happiest with an engineering puzzle in front of him.', 'The Cossacks of the steppe (personal friend of nearly every major clan leader); Warlord Romanov; to a lesser degree Warlord Seriyev', 'Warlord Sokolov (undeclared war of raids and sabotage); Warlord Orloff', 'Called "The Mountain King", the third of his family to rule the Caucasus and the deserts east of the Caspian, and the only entirely unaugmented human among the Warlords. An NGR-trained cybernetics engineer, he had a hand in designing the Wingrider, the Lynx armor and the White Tiger cyborg, and fields the smallest War Camp in Russia (26,000 troops; white, silver and black; leaping tiger symbol) while waging a campaign of psychological warfare against Sokolov.', 'Rifts World Book 17: Warlords of Russia p.43-44'),
('warlord-boris-orloff', 'Boris Anatolii Orloff', NULL, 'Warlord', 'rifts', 'Human, full conversion Heavy Machine', '8th level Heavy ''Borg and Warlord (with special training as a Warlord and assassin skills)', 8, 'Diabolic', '29', '11 feet (3.3 m)', '1,100 lbs (495 kg)', '{"IQ":16,"ME":8,"MA":13,"PS":40,"PP":25,"PB":15,"Spd":88}', NULL, NULL, 270, 3, NULL, NULL, NULL, '{"attacks":7,"initiative":5,"strike":9,"pull":5,"roll":5,"damage":4,"parry":8,"dodge":8}', '+1 to body/flip throw. Printed as +5 to pull/roll with punch/fall and +8 to parry or dodge. P.S. 40 is robotic; P.P. 25 is bionic; P.E. N/A; M.E. 8 (and crumbling). Spd 88 (60 mph, 96 kph). Hit Points and S.D.C. not applicable: Standard Heavy Machine, 270 M.D.C. main body, plus 280 M.D.C. from heavy body armor, which he always wears into battle.', '[{"name":"Radio: Basic","pct":98},{"name":"Intelligence","pct":95},{"name":"Interrogation","pct":95},{"name":"Literacy: Russian and Euro","pct":90},{"name":"Computer Operation","pct":98},{"name":"Pilot: Hovercycle","pct":98},{"name":"Pilot: Jet Pack","pct":80},{"name":"Horsemanship","pct":88},{"name":"Tracking","pct":98},{"name":"Escape Artist","pct":80},{"name":"Camouflage","pct":85},{"name":"Military Etiquette","pct":98}]', 'The book lists Intelligence twice (95% and 98%) and Interrogation twice (95% and 90%); the first printed figure is recorded. Sniper (+1 on aimed shot); Boxing. Hand to Hand: Assassin; W.P. Heavy Energy Weapons, W.P. Energy Rifles, W.P. Knife, W.P. Sword; paired weapons.', NULL, 'None', 'None', NULL, 'Full conversion Heavy Machine with his real human face and real hair; cybernetic eyes made to look like golden cat''s eyes, with a multi-optic package; all basic features and weapons of the typical Heavy Machine cyborg and more; swaps forearm and hand weapons at whim', 'Heavy cyborg armor (280 M.D.C.), worn 75% of the time; always carries heavy weapons and explosives', 'Roughly 150 million universal credits; 4.6 billion credits in diamonds, gold and other resources; plus his cities, the alien bionics and manufacturing plants at Donetsk, land holdings, War Camp and mineral rights', 'A cruel, vengeful sadist who cares for nothing except himself and conquest, and who talks about power and torture with a child''s delight. His temper is explosive and often fatal to bystanders, he would rather win by ambush or betrayal than in a fair fight, and his sanity is steadily failing.', 'Warlord Sokolov (a strained, on-and-off partnership)', 'In order: Warlord Romanov, Warlord Burgasov, Warlord Seriyev, the Sovietski, the Cossacks, Warlord Kolodenko, Warlord Alekseyevna', 'Nicknamed "The Snowdemon", "The Butcher" or "Orloff the Mad". At 16 he helped his father massacre the alien refugees who had built their cyborg army, and two years later he killed his father to take the title. He has since seized a quarter of the Sovietski''s territory and 18% of Sokolov''s, and rules about a million fearful subjects from Donetsk and Kurybyshev with the second largest War Camp in Russia (87,400 troops, 60% full conversion cyborgs; black on white; fanged serpent symbol).', 'Rifts World Book 17: Warlords of Russia p.46'),
('warlord-sonya-romanov', 'Sonya Tatyana Romanov', NULL, 'Warlord', 'rifts', 'Human, full conversion Heavy Machine (female)', '9th level Heavy Borg and Warlord; ex-War-Knight', 9, 'Scrupulous', '36', '10 feet (3 m)', '850 lbs (382.5 kg)', '{"IQ":17,"ME":13,"MA":24,"PS":35,"PP":24,"PB":19}', NULL, NULL, 270, 12, 66, NULL, NULL, '{"attacks":7,"initiative":3,"strike":7,"parry":8,"dodge":8,"disarm":2,"pull":5,"roll":5}', '+1 to body/flip throw critical; +5 to save vs Horror Factor. Critical strike on an unmodified 18, 19 or 20; jump kick; entangle; leap attack. Printed as +5 to pull/roll with punch/fall. P.S. 35 is robotic; P.P. 24 is bionic; P.E. N/A. Bionic speed 100 mph (160 km). Hit Points and S.D.C. not applicable: Standard Heavy Machine, 270 M.D.C. main body, plus 280 M.D.C. from heavy body armor; usually wears medium or heavy cyborg armor into battle.', '[{"name":"Radio: Basic","pct":98},{"name":"Intelligence","pct":95},{"name":"Interrogation","pct":95},{"name":"Literacy: Russian and Euro","pct":90},{"name":"Computer Operation","pct":98},{"name":"Pilot: Hovercycle","pct":98},{"name":"Pilot: Jet Pack","pct":80},{"name":"Horsemanship: Knight","pct":90},{"name":"Escape Artist","pct":70},{"name":"Lore: Demons and Monsters","pct":90},{"name":"Lore: Religion","pct":90},{"name":"Climbing","pct":95},{"name":"Russian History","pct":60},{"name":"Streetwise","pct":61},{"name":"Military Etiquette","pct":98}]', 'The book lists Intelligence twice (95% and 98%) and Radio: Basic twice (98% and 95%); the first printed figure is recorded. Climbing is printed 95%/85%. Sniper (+1 on aimed shot); Boxing. Hand to Hand: Martial Arts; W.P. Heavy Energy Weapons, W.P. Energy Rifles, W.P. Knife, W.P. Sword; paired weapons.', NULL, 'None', 'Formerly a major psionic; cyborg conversion left only Total Recall and Empathy. 66 I.S.P.', NULL, 'Full conversion Heavy Machine with her real human face; all basic features and weapons typical of Heavy Machine cyborgs and more; changes forearm and hand weapons to suit the situation, favoring heavy and long-range weapons for serious combat and the sword otherwise', 'Demon slaying rune dagger: a greatest rune weapon with healing and spell casting abilities; a soul drinker that can devour the life force of lesser vampires, lesser and greater demons, and the fragmented life essences of Alien Intelligences as often as once every 48 hours. Medium or heavy cyborg armor (heavy: 280 M.D.C.)', 'Roughly 500 million universal credits; 100 million in Rubles; 12.4 billion credits in bionics and industrial trade goods and resources; plus her cities, the Novyet manufacturing plants, land holdings and War Camp', 'The model of a knight: brave, truthful and kind, yet also self-assured, inventive and fast on her feet, with a clear sense of her own limits. She is firm but even-handed, hears out every side of a dispute, and holds to the dream of a peaceful, reunited Russia.', 'The Sovietski; Warlord Seriyev (whom she trusts too much); Warlord Kolodenko', 'Warlord Orloff above all; Warlord Sokolov', 'Called "Sonya the Great". An orphan who took the Romanov name after a fever dream, she rose from camp cook to War-Knight, was rebuilt as a Heavy Machine after a battle with Brodkil, and became Warlord when she exposed her predecessor''s pact with a demon lord and wounded him with her rune dagger in a trial by combat. Her Sphere, centered on Kiev with her Winter Palace at Kharkov, is the most prosperous and orderly in Russia (War Camp of 75,800; gold and purple; crossed swords under a dove).', 'Rifts World Book 17: Warlords of Russia p.50-51'),
('warlord-igor-seriyev', 'Igor Seriyev', NULL, 'Warlord', 'rifts', 'Human, partial cyborg', 'Effectively a 10th level Assassin and Warlord', 10, 'Unprincipled', '34', '6 feet, 5 inches (1.98 m)', '300 lbs (136 kg)', '{"IQ":20,"ME":20,"MA":23,"PS":18,"PP":19,"PE":14,"PB":15}', 49, 32, 22, 6, NULL, NULL, NULL, '{"attacks":6,"initiative":3,"strike":7,"parry":9,"dodge":9,"roll":3,"pull":3}', '+6 to save vs Horror Factor. Critical strike on an unmodified 18-20; jump kick (critical); entangle. Attacks per melee include all bonuses. NOT included in the listed bonuses: the ear implant with amplified hearing gives +3 on initiative, +1 to parry, +2 to dodge. P.S. 18 and P.P. 19 are the human values; the bionic limbs are P.S. 22 and P.P. 22. Spd 60 mph (96 km), bionic. M.D.C.: bionic legs 80 each, bionic arm 40, head 60, main body (reinforced skeleton) 22. In battle wears medium to heavy environmental armor (50-100 M.D.C.) or Light Cyborg Armor (140 M.D.C.).', '[{"name":"Language: Russian","pct":98},{"name":"Language: Chinese","pct":98},{"name":"Language: Euro","pct":98},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: American","pct":98},{"name":"Computer Hacking","pct":71},{"name":"Palming","pct":86},{"name":"Streetwise","pct":76},{"name":"Forgery","pct":91},{"name":"Disguise","pct":96},{"name":"Cryptography","pct":98},{"name":"Radio: Scramblers","pct":98},{"name":"Surveillance Systems","pct":98},{"name":"Tracking","pct":98},{"name":"Horsemanship","pct":95},{"name":"Climbing","pct":98},{"name":"Wilderness Survival","pct":81},{"name":"Pilot: Hovercycle","pct":98}]', 'Computer Operation and Computer Programming are printed with no percentage of their own (the list runs: computer operation, computer programming, computer hacking 71%). Climbing is printed 98%/88%. Boxing. Hand to Hand: Martial Arts; W.P. Knife, W.P. Energy Rifles, W.P. Energy Pistols; paired weapons.', NULL, 'None', 'None', NULL, 'One bionic arm, two bionic legs, one bionic eye; Type AA cyber-disguise (an artificial but human-looking face); gyro-compass; wrist garrote; forearm weapon; retractable Vibro-Blade; laser finger (1D4 M.D.); clock calendar; universal headjack and ear implant with amplified hearing', 'Medium to heavy environmental armor (50-100 M.D.C.) or Light Cyborg Armor (140 M.D.C.); usually accompanied by two Assassin ''Borgs and two Mantis', 'Roughly 600 million universal credits; 5.2 billion credits in personal wealth and liquid assets; plus his Sphere of Influence, cities, manufacturing, bionics, land holdings, War Camp and criminal organization', 'Unflappable and smooth in any crisis, an inventive schemer and a superb liar. Behind the cultured manner he treats everyone as a game piece and will sell out any friend to win, though Romanov is the one person he honestly admires.', 'Warlord Romanov; the Sovietski; outwardly friendly with Warlord Kolodenko; the Black Market and the Russian Mafia', 'Warlords Orloff and Sokolov; wary mutual respect with Warlord Burgasov', 'Nicknamed "The Rat of Minsk" or "The Black Knight". He won his lands by intrigue rather than battle and secretly runs a murder-for-hire and extortion network, with spies in every War Camp except Kolodenko''s, whose services four other Warlords have bought without knowing whose they were. From his castle in Minsk he rules about 600,000 people with an official War Camp of 36,000 (yellow and blue; dagger and rose symbol) and roughly 30,000 more covert agents.', 'Rifts World Book 17: Warlords of Russia p.53'),
('warlord-grigori-sokolov', 'Grigori Levka Sokolov', NULL, 'Warlord', 'rifts', 'Human, full conversion Heavy Machine', '11th level Heavy ''Borg and Warlord', 11, 'Diabolic', '58 (looks about 40)', '12 feet (3.6 m)', '1,200 lbs (540 kg)', '{"IQ":9,"ME":8,"MA":11,"PS":50,"PP":24,"PB":11,"Spd":65}', NULL, NULL, 270, 4, NULL, NULL, NULL, '{"attacks":7,"initiative":3,"strike":7,"parry":10,"dodge":10,"pull":4,"roll":3}', 'Impervious to Horror Factor (special; except from Kolodenko). Critical strike on an unmodified 18, 19 or 20; jump kick (critical strike); karate punch; entangle; leap attack; body flip/throw. P.S. 50 is robotic; P.P. 24 is bionic; P.E. N/A. Spd 65 (44 mph, 70 kph). Heavy Machine: 270 M.D.C. main body, plus 280 M.D.C. from heavy body armor with a demonic face plate. The block prints no Hit Points or S.D.C. line.', '[{"name":"Intelligence","pct":98},{"name":"Tracking","pct":90},{"name":"Interrogation","pct":90},{"name":"Find Contraband","pct":80},{"name":"Language: Russian and German","pct":98},{"name":"Horsemanship: Exotic Animals","pct":90},{"name":"Pilot: Jet Pack","pct":86},{"name":"Climbing","pct":95},{"name":"Cardsharp","pct":68},{"name":"Streetwise","pct":64},{"name":"Dancing","pct":85},{"name":"Pilot: Hovercycle","pct":82},{"name":"Military Etiquette","pct":98}]', 'Illiterate. Pilot: Hover Vehicles and Pilot: Tank are printed with no percentage. Climbing is printed 95%/85%. Hand to Hand: Martial Arts, Wrestling and Boxing; paired weapons; W.P. Energy Rifle, W.P. Energy Pistol, W.P. Heavy Energy, W.P. Heavy, W.P. Sword, W.P. Knife, W.P. Axe.', NULL, 'None', 'None', NULL, 'Full conversion Heavy Machine with a realistic but artificial human face, covered by a demonic face plate in combat; all basic weapons and features of the typical Heavy Machine cyborg and more; a number of concealed built-in weapons', 'Heavy body armor with demonic face plate (280 M.D.C.); heavy weapons; a small arsenal of magic weapons and items; a flying throne', 'Roughly 90 million universal credits; one billion in diamonds, gold and other resources; plus his Sphere of Influence, manufacturing plants, land holdings and War Camp', 'Loud, boastful, spiteful and violent, a dull-witted bully who uses his size to win arguments and respects nobody. He kills without a second thought, and a growing fixation on Kolodenko is turning his lifelong brutality into outright paranoia.', 'Warlord Orloff, the only person he trusts', 'Warlord Kolodenko first (the only man he has ever feared); the Sovietski, Cossacks, Poles, Ukrainians and every other Warlord; D-Bees and all nonhumans', 'Called "The Demonfist". A product of a murderous upbringing, he won his title in a duel 35 years ago and has survived ever since on animal cunning and remarkable luck. He has no capital, travelling with his War Camp (77,500 troops; blue and silver; eagle claw symbol), and rules the poorest and most backward Sphere in Russia; frustrated by Kolodenko''s guerilla campaign, he has lately sent his raiders rampaging across every neighboring border.', 'Rifts World Book 17: Warlords of Russia p.56'),
('general-katya-nikoforov', 'General Katya Nikoforov', NULL, 'Director of the Sovietski', 'rifts', NULL, '10th level Military Specialist; Director of the Sovietski and General in the Army', 10, 'Scrupulous', '53 (looks 40)', NULL, NULL, '{"IQ":18,"ME":15,"MA":21,"PS":28,"PP":24,"PB":19}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Quick Stats only: no attacks, bonuses or skills are printed. P.S. 28 and P.P. 24 are bionic; P.E. N/A. Bionic speed 100 mph (160 km). Hit Points and S.D.C. are printed as not applicable, and the M.D.C. line reads Light Machine, Partial Cyborg, with no number.', NULL, NULL, NULL, NULL, NULL, NULL, 'Light Machine partial cyborg: two bionic arms and hands made to look human (75% sensitivity); reinforced neck, head and spine; various cybernetic implants and bionic weapons', 'Travels with a retinue of 4D6+12 bodyguards, aides and advisors; outside New Moscow, a company of troops including a platoon of Heavy Cyborgs and a platoon of Cyborg Shocktroopers', NULL, 'Brilliant, perceptive and endlessly curious, a self-described public servant with little appetite for power who can still make a ruthless call. She is committed to human rule of the Earth and deeply distrustful of D-Bees, though she argues against wiping them out.', 'Warlord Romanov and Warlord Seriyev (friendly relations with the Sovietski); 88% of the Soviet military', 'Warlord Orloff and Warlord Sokolov; supernatural menaces', 'The first woman to lead the Sovietski, in office since 99 P.A. after a career that made her a General at 38 and a Politburo member at 42; friends call her "Katyana". She governs from the Kremlin in New Moscow for most of the year and tours the outlying cities for the rest. Orloff''s seizure of Soviet territory is the one failure on her record, and she is quietly massing forces on the southern border to prevent a repeat and, if possible, win it back.', 'Rifts World Book 17: Warlords of Russia p.207');
